# Bài giảng HSK 3 (HSK 3.0). Bài nào chưa có ở đây thì app chỉ dạy từ vựng + bài tập (4 bước).
# [từ] đánh dấu từ trọng tâm cho bài tập điền từ.
UNITS3 = [
# ---------------- 1
{"title":"Nhà mới","topic":"Nhà cửa, đồ dùng; câu 把 (1), 刚 / 刚才, bổ ngữ kết quả 到 / 住 / 走 / 上",
"goals":["Gọi tên phòng, đồ dùng trong nhà","Dùng câu 把 để nói đặt / chuyển đồ vật đi đâu","Phân biệt 刚 và 刚才","Dùng bổ ngữ kết quả 到, 住, 走, 上"],
"dialogue":[("小米","龙，听说你搬家了？新房子怎么样？","Long, nghe nói bạn chuyển nhà rồi à? Nhà mới thế nào?"),("龙","挺好的，在一个新小区，我住在十二层。","Khá tốt, ở một khu chung cư mới, mình ở tầng mười hai."),("小米","有电梯吗？","Có thang máy không?"),("龙","有。我刚搬进去，东西还没放好。","Có. Mình vừa dọn vào, đồ đạc còn chưa xếp xong."),("小米","我周末去帮你吧！你想把沙发放在哪儿？","Cuối tuần mình qua giúp nhé! Bạn muốn đặt sofa ở đâu?"),("龙","我想把沙发放在窗户旁边，把冰箱搬到厨房里。","Mình muốn đặt sofa cạnh cửa sổ, chuyển tủ lạnh vào bếp."),("小米","好。对了，你刚才说的邻居是谁？","Được. À, người hàng xóm bạn nói lúc nãy là ai?"),("龙","是一位老人，很热情。我已经记住他的名字了。","Là một cụ già, rất nhiệt tình. Mình đã nhớ được tên cụ rồi.")],
"grammar":[
{"title":"Câu 把 (1): đem cái gì đặt / chuyển tới đâu","formula":"Chủ ngữ + 把 + Vật + Động từ + 在 / 到 + Nơi chốn",
"explain":"Câu <b>把</b> nhấn mạnh việc <b>xử lý một vật cụ thể</b> và kết quả của việc đó. Mẫu hay gặp nhất là đặt / chuyển vật tới một chỗ:<br>我<b>把</b>沙发<b>放在</b>窗户旁边。 (Tôi đặt sofa cạnh cửa sổ.)<br>他<b>把</b>冰箱<b>搬到</b>厨房里。<br>Lưu ý: vật sau 把 phải <b>xác định</b> (người nghe biết là cái nào), và động từ <b>không đứng một mình</b> mà phải có phần sau (在…, 到…, 了, bổ ngữ…).",
"examples":[("我[把]沙发放在窗户旁边。","Tôi đặt sofa cạnh cửa sổ."),("请[把]书放在桌子上。","Hãy đặt sách lên bàn."),("他[把]冰箱搬到厨房里了。","Anh ấy chuyển tủ lạnh vào bếp rồi."),("你[把]手机放在哪儿了？","Bạn để điện thoại ở đâu rồi?")],
"note":"Sai: 我把沙发放。 (thiếu phần sau động từ). Phủ định đặt 没/不 trước 把: 我没把书放在桌子上。"},
{"title":"刚 và 刚才","formula":"刚 + Động từ (phó từ) · 刚才 (danh từ thời gian, đứng đầu câu hoặc trước động từ)",
"explain":"Cả hai đều nghĩa \"vừa mới\" nhưng khác loại từ:<br>• <b>刚 / 刚刚</b> là phó từ, đứng ngay trước động từ: 我<b>刚</b>到。 Có thể đi với thời lượng: 我刚来三天。<br>• <b>刚才</b> là danh từ chỉ thời điểm \"lúc nãy\", đứng được đầu câu, có thể đi với 不/没: <b>刚才</b>你去哪儿了？ 我刚才没听清楚。<br><b>刚才</b> chỉ vài phút trước; <b>刚</b> có thể là vài ngày trước (theo cảm nhận người nói).",
"examples":[("我[刚]搬进去。","Tôi vừa dọn vào."),("[刚才]你说什么？","Lúc nãy bạn nói gì?"),("他刚来中国三个月。","Anh ấy mới đến Trung Quốc ba tháng."),("[刚才]的电话是谁打的？","Cuộc gọi lúc nãy là ai gọi?")],
"note":"Sai: 刚你去哪儿了？ (刚 không đứng đầu câu). Sai: 我刚不在。 Đúng: 我刚才不在。"},
{"title":"Bổ ngữ kết quả: V + 到 / 住 / 走 / 上","formula":"Động từ + 到 (đạt được) / 住 (giữ chặt) / 走 (đi mất) / 上 (đóng, khép, đạt)",
"explain":"Thêm 4 bổ ngữ kết quả hay gặp:<br>• <b>到</b>: đạt được mục đích — 找<b>到</b> (tìm thấy), 买<b>到</b>, 收<b>到</b><br>• <b>住</b>: giữ lại, cố định — 记<b>住</b> (nhớ được), 站<b>住</b> (đứng lại)<br>• <b>走</b>: rời khỏi chỗ cũ — 拿<b>走</b> (cầm đi), 带<b>走</b><br>• <b>上</b>: khép lại / đạt tới — 关<b>上</b>门 (đóng cửa lại), 穿<b>上</b>, 考<b>上</b> (thi đỗ)<br>Phủ định dùng 没: 我没找到。",
"examples":[("我已经记[住]他的名字了。","Tôi đã nhớ được tên ông ấy rồi."),("你找[到]钥匙了吗？","Bạn tìm thấy chìa khóa chưa?"),("请关[上]门。","Làm ơn đóng cửa lại."),("谁把我的书拿[走]了？","Ai cầm mất sách của tôi rồi?")],
"note":"记得 (nhớ, còn nhớ) khác 记住 (ghi nhớ được, sau khi cố nhớ)."}],
"tip":"Ở Trung Quốc người ta hay mời hàng xóm, bạn bè tới \"温居\" (ăn mừng nhà mới). Khách thường mang quà nhỏ như trái cây."},
# ---------------- 2
{"title":"Đi khám bệnh","topic":"Cơ thể, ốm đau; câu bị động 被, …极了 / 得很 / 坏了, câu phản vấn 不是…吗",
"goals":["Mô tả triệu chứng: sốt, cảm, đau","Dùng câu bị động với 被","Nói mức độ cao: 好极了, 累坏了, 冷得很","Nhấn mạnh bằng câu phản vấn 不是…吗？"],
"dialogue":[("医生","你哪儿不舒服？","Bạn thấy khó chịu ở đâu?"),("龙","我头疼，还有点儿发烧。昨天晚上被雨淋了。","Tôi đau đầu, còn hơi sốt. Tối qua bị mưa ướt hết."),("医生","你没带伞吗？","Bạn không mang ô à?"),("龙","带了，可是我的伞被风刮坏了。","Có mang, nhưng ô của tôi bị gió thổi hỏng rồi."),("医生","是感冒。不是很严重，不用住院，多喝水，好好儿休息。","Là cảm. Không nghiêm trọng lắm, không cần nằm viện, uống nhiều nước, nghỉ ngơi cho tốt."),("龙","谢谢医生！我今天累坏了。","Cảm ơn bác sĩ! Hôm nay tôi mệt rã rời."),("小米","龙，你不是说今天去锻炼吗？","Long, chẳng phải bạn nói hôm nay đi tập à?"),("龙","不去了，先把身体养好。健康最重要！","Không đi nữa, phải dưỡng sức khỏe cho tốt trước. Sức khỏe quan trọng nhất!")],
"grammar":[
{"title":"Câu bị động với 被","formula":"Chủ ngữ (người/vật chịu tác động) + 被 + (Người làm) + Động từ + phần khác",
"explain":"Câu <b>被</b> dùng khi chủ ngữ <b>chịu</b> một tác động, thường là chuyện không mong muốn:<br>我的伞<b>被</b>风刮坏了。 (Ô của tôi bị gió thổi hỏng.)<br>Có thể bỏ người làm: 我的手机<b>被</b>拿走了。<br>Giống câu 把, động từ phải có phần sau (了, bổ ngữ…). Phủ định: <b>没被</b>: 我没被老师批评。",
"examples":[("我的伞[被]风刮坏了。","Ô của tôi bị gió thổi hỏng rồi."),("我的蛋糕[被]弟弟吃了。","Bánh của tôi bị em trai ăn mất."),("他[被]雨淋了。","Anh ấy bị mưa làm ướt."),("书[被]谁拿走了？","Sách bị ai cầm đi rồi?")],
"note":"So sánh: 风把伞刮坏了 (câu 把, nhấn người/vật gây ra) ↔ 伞被风刮坏了 (câu 被, nhấn vật bị ảnh hưởng). Hai câu cùng nghĩa."},
{"title":"Mức độ cao: Adj + 极了 / 得很 / 坏了","formula":"Tính từ + 极了 · Tính từ + 得很 · Tính từ/Động từ + 坏了",
"explain":"Ba cách nói \"cực kỳ\" đứng <b>sau</b> tính từ:<br>• <b>极了</b>: cực kỳ (khen hoặc chê đều được) — 好<b>极了</b>, 累<b>极了</b><br>• <b>得很</b>: rất (khẩu ngữ) — 冷<b>得很</b><br>• <b>坏了</b>: …muốn chết, …rã rời (thường với cảm giác khó chịu hoặc cảm xúc mạnh) — 累<b>坏了</b>, 饿<b>坏了</b>, 高兴<b>坏了</b>",
"examples":[("我今天累[坏了]。","Hôm nay tôi mệt rã rời."),("这个蛋糕好吃[极了]！","Cái bánh này ngon cực kỳ!"),("北方的冬天冷[得很]。","Mùa đông miền Bắc lạnh lắm."),("孩子们高兴坏了。","Bọn trẻ vui muốn xỉu.")],
"note":"Đã dùng 极了/得很/坏了 thì không thêm 很 phía trước: Sai: 很好极了。"},
{"title":"Câu phản vấn: 不是…吗？","formula":"不是 + … + 吗？ (= rõ ràng là…, sao lại…?)",
"explain":"Câu hỏi <b>không cần trả lời</b>, dùng để nhắc lại điều người nói cho là đúng, kèm chút ngạc nhiên hoặc trách nhẹ:<br>你<b>不是</b>说今天去锻炼<b>吗</b>？ (Chẳng phải bạn nói hôm nay đi tập sao?)",
"examples":[("你[不是]说今天去锻炼[吗]？","Chẳng phải bạn nói hôm nay đi tập sao?"),("你不是带伞了吗？","Chẳng phải bạn mang ô rồi sao?"),("他不是你的同学吗？","Cậu ấy chẳng phải bạn học của bạn sao?"),("今天不是星期六吗？","Hôm nay chẳng phải thứ bảy à?")],
"note":"Giọng điệu đi lên ở 吗, nhấn vào phần sau 不是."}],
"tip":"Đi khám ở Trung Quốc: đầu tiên 挂号 (lấy số), sau đó 看病 (khám), cuối cùng 拿药 (lấy thuốc)."},
# ---------------- 3
{"title":"Ăn gì cho ngon","topic":"Đồ ăn, đồ uống, dụng cụ ăn; 越来越, 越…越…, bổ ngữ khả năng 得 / 不",
"goals":["Gọi tên đồ ăn, đồ uống, bát đũa","Nói thay đổi theo thời gian với 越来越","Nói hai việc tăng cùng nhau với 越…越…","Nói có thể / không thể làm được bằng bổ ngữ khả năng"],
"dialogue":[("安娜","龙，你会用筷子吗？","Long, bạn biết dùng đũa không?"),("龙","会啊，我从小就用筷子。你呢？","Biết chứ, mình dùng đũa từ nhỏ. Còn bạn?"),("安娜","我来中国以后才开始学，现在用得越来越好了。","Mình sang Trung Quốc rồi mới bắt đầu học, giờ dùng càng ngày càng giỏi."),("龙","今天的菜太多了，我们吃得完吗？","Hôm nay đồ ăn nhiều quá, chúng ta ăn hết nổi không?"),("安娜","吃不完就带回家。这个蛋糕越吃越好吃！","Ăn không hết thì mang về nhà. Cái bánh này càng ăn càng ngon!"),("龙","你别吃太多甜的。要不要喝点儿饮料？","Bạn đừng ăn đồ ngọt nhiều quá. Có muốn uống chút gì không?"),("安娜","我要一瓶矿泉水，渴极了。","Mình lấy một chai nước khoáng, khát quá."),("龙","服务员，再给我们一个盘子和两个勺子，谢谢！","Phục vụ ơi, cho chúng tôi thêm một cái đĩa và hai cái thìa, cảm ơn!")],
"grammar":[
{"title":"越来越 + Tính từ: càng ngày càng…","formula":"Chủ ngữ + 越来越 + Tính từ / Động từ tâm lý",
"explain":"<b>越来越</b> diễn tả mức độ <b>tăng dần theo thời gian</b>: 天气<b>越来越</b>冷了。 Cuối câu thường có <b>了</b> (đã thay đổi).<br>Không dùng 很, 非常 sau 越来越: Sai: 越来越很好。",
"examples":[("我用筷子用得[越来越]好了。","Tôi dùng đũa càng ngày càng giỏi."),("天气[越来越]冷了。","Trời càng ngày càng lạnh."),("他[越来越]喜欢中国菜了。","Anh ấy càng ngày càng thích món Trung."),("城市越来越大了。","Thành phố càng ngày càng lớn.")],
"note":"越来越 + động từ tâm lý (喜欢, 想, 了解…) cũng được: 我越来越想家了。"},
{"title":"越 A 越 B: càng A càng B","formula":"Chủ ngữ + 越 + A + 越 + B",
"explain":"B thay đổi <b>theo</b> A: A càng nhiều/mạnh thì B càng…<br>这个蛋糕<b>越</b>吃<b>越</b>好吃。 (càng ăn càng ngon)<br>雨<b>越</b>下<b>越</b>大。 (mưa càng lúc càng to)<br>Hai vế có thể có chủ ngữ khác nhau: 你<b>越</b>说，他<b>越</b>生气。",
"examples":[("这个蛋糕[越]吃[越]好吃！","Cái bánh này càng ăn càng ngon!"),("雨[越]下[越]大。","Mưa càng lúc càng to."),("汉语越学越有意思。","Tiếng Trung càng học càng thú vị."),("你越说，他越生气。","Bạn càng nói, anh ấy càng giận.")],
"note":"越…越… không dùng với 很: Sai: 越吃越很好吃。"},
{"title":"Bổ ngữ khả năng: V + 得 / 不 + kết quả","formula":"Động từ + 得 + bổ ngữ (làm được) · Động từ + 不 + bổ ngữ (không làm được)",
"explain":"Chèn <b>得</b> (được) hoặc <b>不</b> (không) giữa động từ và bổ ngữ kết quả/xu hướng để nói <b>có khả năng đạt kết quả</b> hay không:<br>吃<b>得</b>完 (ăn hết được) / 吃<b>不</b>完 (ăn không hết)<br>看<b>得</b>懂 / 看<b>不</b>懂 · 听<b>得</b>清楚 / 听<b>不</b>清楚 · 回<b>得</b>来 / 回<b>不</b>来<br>Hỏi: 吃得完吃不完？ hoặc 吃得完吗？",
"examples":[("今天的菜太多了，我们吃[得]完吗？","Hôm nay đồ ăn nhiều quá, chúng ta ăn hết nổi không?"),("吃[不]完就带回家。","Ăn không hết thì mang về nhà."),("这本书你看得懂吗？","Quyển sách này bạn đọc hiểu được không?"),("太远了，我听不清楚。","Xa quá, tôi nghe không rõ.")],
"note":"不能吃完 (không được phép ăn hết) ≠ 吃不完 (không có khả năng ăn hết). Người Việt hay nhầm hai cái này."}],
"tip":"Trên bàn ăn Trung Quốc đừng cắm đũa thẳng đứng vào bát cơm, vì giống nén hương cúng người đã mất."},
# ---------------- 4
{"title":"Đi mua quần áo","topic":"Quần áo, thanh toán, tiền lẻ; so sánh 一样 / 更 / 不比, câu 把 (2)",
"goals":["Hỏi cỡ, đổi đồ, thanh toán bằng thẻ","So sánh bằng với 跟…一样","So sánh hơn với 更 / 还, và 不比","Dùng 把 + vật + 换成 / 给"],
"dialogue":[("龙","这件衬衫多少钱？","Cái áo sơ mi này bao nhiêu tiền?"),("服务员","一百八十九块五毛。您穿多大的？","Một trăm tám mươi chín tệ năm hào. Anh mặc cỡ bao nhiêu?"),("龙","这件有点儿小，能把它换成大一号的吗？","Cái này hơi nhỏ, đổi sang cỡ lớn hơn một số được không?"),("服务员","可以。这件大小跟那件一样，颜色不一样。","Được. Cái này cỡ giống cái kia, màu thì khác."),("龙","黄色的比蓝色的更好看。","Màu vàng đẹp hơn màu xanh."),("小米","我觉得蓝色的不比黄色的难看，还更便宜。","Mình thấy màu xanh không xấu hơn màu vàng, lại còn rẻ hơn."),("龙","好，就要蓝色的。可以用信用卡吗？","Được, lấy màu xanh. Dùng thẻ tín dụng được không?"),("服务员","可以，请把卡给我。一共一百五十块。","Được, xin đưa thẻ cho tôi. Tổng cộng một trăm năm mươi tệ.")],
"grammar":[
{"title":"So sánh bằng: A 跟 B 一样 (+ Tính từ)","formula":"A + 跟 + B + 一样 (+ Tính từ) · Phủ định: A + 跟 + B + 不一样",
"explain":"Nói A <b>giống</b> B: 这件<b>跟</b>那件<b>一样</b>。 Muốn nói giống ở điểm nào thì thêm tính từ: 我<b>跟</b>他<b>一样</b>高。 (Tôi cao bằng anh ấy.)<br>Phủ định đặt 不 trước 一样: 颜色<b>不一样</b>。",
"examples":[("这件大小[跟]那件[一样]。","Cái này cỡ giống cái kia."),("我跟他一样高。","Tôi cao bằng anh ấy."),("颜色不[一样]。","Màu không giống nhau."),("北京的冬天跟这儿不一样。","Mùa đông Bắc Kinh khác ở đây.")],
"note":"Sai: 我跟他一样很高。 Không thêm 很 sau 一样."},
{"title":"A 比 B 更 / 还 + Tính từ · A 不比 B + Tính từ","formula":"A + 比 + B + 更/还 + Tính từ · A + 不比 + B + Tính từ",
"explain":"<b>更 / 还</b> trước tính từ trong câu 比 nhấn mạnh \"hơn nữa\" (B vốn đã…, A còn…hơn): 黄色的比蓝色的<b>更</b>好看。<br><b>A 不比 B + Tính từ</b> nghĩa là \"A không hơn B\" (ngang ngang hoặc kém), thường để <b>phản bác</b> ý người khác: 蓝色的<b>不比</b>黄色的难看。 (Màu xanh đâu có xấu hơn màu vàng.)<br>Nhớ lại HSK 2: muốn nói \"kém\" thì dùng 没有.",
"examples":[("黄色的比蓝色的[更]好看。","Màu vàng đẹp hơn màu xanh."),("蓝色的[不比]黄色的难看。","Màu xanh không xấu hơn màu vàng."),("今天比昨天还冷。","Hôm nay còn lạnh hơn hôm qua."),("我不比你聪明。","Tôi đâu có thông minh hơn bạn.")],
"note":"更/还 dùng trong câu 比; 很/非常/太 thì KHÔNG dùng trong câu 比."},
{"title":"Câu 把 (2): 把 + vật + 换成 / 给 / 交给","formula":"Chủ ngữ + 把 + Vật + Động từ + 成 + Kết quả · 把 + Vật + 给 + Người",
"explain":"Hai mẫu câu 把 thường dùng khi mua bán:<br>• Đổi A thành B: 能<b>把</b>它<b>换成</b>大一号的吗？<br>• Đưa vật cho ai: 请<b>把</b>卡<b>给</b>我。 / <b>把</b>作业<b>交给</b>老师。",
"examples":[("能[把]它换成大一号的吗？","Đổi nó sang cỡ lớn hơn một số được không?"),("请[把]卡给我。","Xin đưa thẻ cho tôi."),("我想把美元换成人民币。","Tôi muốn đổi đô la sang nhân dân tệ."),("你把这本书给他吧。","Bạn đưa quyển sách này cho anh ấy đi.")],
"note":"Tiền Trung Quốc: 1 块 (元) = 10 毛 (角) = 100 分. Nói 189,5 tệ là 一百八十九块五(毛)."}],
"tip":"Ở Trung Quốc gần như ai cũng trả bằng điện thoại (微信支付, 支付宝). Người nước ngoài giờ cũng liên kết được thẻ Visa/Master vào hai app này."},
# ---------------- 5
{"title":"Bốn mùa và ngày lễ","topic":"Mùa, thời tiết, lễ tết, nghỉ lễ; 除了…以外, 该…了, 从…起",
"goals":["Nói về bốn mùa, gió, mặt trời, mặt trăng","Dùng 除了…以外 để nói \"ngoài… ra\"","Nhắc \"đến lúc làm gì rồi\" với 该…了","Nói mốc bắt đầu với 从…起"],
"dialogue":[("安娜","龙，越南有四季吗？","Long, Việt Nam có bốn mùa không?"),("龙","北方有四季，南方只有两个季节：雨季和旱季。","Miền Bắc có bốn mùa, miền Nam chỉ có hai mùa: mùa mưa và mùa khô."),("安娜","我最喜欢秋天，凉快极了。","Mình thích mùa thu nhất, mát cực kỳ."),("龙","中秋节的月亮特别大。除了吃月饼以外，我们还看月亮。","Trung thu trăng to đặc biệt. Ngoài ăn bánh trung thu ra, tụi mình còn ngắm trăng."),("安娜","我们国家除了新年以外，别的节日都不放假。","Nước mình ngoài năm mới ra, các ngày lễ khác đều không được nghỉ."),("龙","从下个星期起，我们放假，有七天假期。","Từ tuần sau trở đi tụi mình nghỉ, có bảy ngày nghỉ."),("安娜","太好了！我们该准备去旅游了。","Tuyệt quá! Đến lúc chuẩn bị đi du lịch rồi."),("龙","对，冬天快到了，该买大衣了。","Đúng, mùa đông sắp tới rồi, phải mua áo khoác thôi.")],
"grammar":[
{"title":"除了…以外，还 / 也 / 都…","formula":"除了 A (以外)，还/也 + B (thêm) · 除了 A (以外)，都 + … (loại trừ)",
"explain":"Hai nghĩa ngược nhau, phân biệt bằng phó từ ở vế sau:<br>• <b>还 / 也</b> = <b>bao gồm thêm</b>: <b>除了</b>吃月饼<b>以外</b>，我们<b>还</b>看月亮。 (ăn bánh, và còn ngắm trăng)<br>• <b>都</b> = <b>loại trừ</b>: <b>除了</b>新年<b>以外</b>，别的节日<b>都</b>不放假。 (trừ năm mới, các lễ khác đều không nghỉ)<br>以外 có thể bỏ.",
"examples":[("[除了]吃月饼[以外]，我们还看月亮。","Ngoài ăn bánh trung thu, chúng tôi còn ngắm trăng."),("[除了]新年以外，别的节日都不放假。","Trừ năm mới, các ngày lễ khác đều không nghỉ."),("除了汉语，他也会说英语。","Ngoài tiếng Trung, anh ấy cũng biết tiếng Anh."),("除了他，大家都来了。","Trừ anh ấy ra, mọi người đều đến rồi.")],
"note":"Nhìn phó từ vế sau: 还/也 → cộng thêm; 都 → trừ ra."},
{"title":"该…了: đến lúc… rồi","formula":"(Chủ ngữ) + 该 + Động từ + 了",
"explain":"<b>该…了</b> nhắc rằng <b>đã đến lúc phải làm gì</b> (theo lẽ thường hoặc theo thời gian):<br>十一点了，我<b>该</b>睡觉<b>了</b>。<br>冬天快到了，<b>该</b>买大衣<b>了</b>。",
"examples":[("我们[该]准备去旅游[了]。","Đến lúc chuẩn bị đi du lịch rồi."),("冬天快到了，[该]买大衣了。","Mùa đông sắp tới, phải mua áo khoác rồi."),("十一点了，你该睡觉了。","Mười một giờ rồi, em nên đi ngủ."),("该你了！","Đến lượt bạn rồi!")],
"note":"该 còn nghĩa là \"nên\" (= 应该): 你该多运动。"},
{"title":"从…起: từ… trở đi","formula":"从 + Thời điểm + 起 (+ Chủ ngữ + Động từ)",
"explain":"<b>从…起</b> chỉ mốc thời gian <b>bắt đầu</b> và kéo dài về sau:<br><b>从</b>下个星期<b>起</b>，我们放假。<br><b>从</b>今天<b>起</b>，我每天跑步。 Có thể nói 从…开始 với nghĩa giống.",
"examples":[("[从]下个星期[起]，我们放假。","Từ tuần sau trở đi, chúng tôi được nghỉ."),("[从]今天起，我每天学习汉语。","Từ hôm nay, ngày nào tôi cũng học tiếng Trung."),("从明年起，他在北京工作。","Từ năm sau, anh ấy làm việc ở Bắc Kinh."),("从那天起，我们成了朋友。","Từ hôm đó, chúng tôi thành bạn.")],
"note":"Chỉ dùng cho thời gian. Nơi chốn thì dùng 从…到… (đã học ở HSK 2)."}],
"tip":"Lễ lớn ở Trung Quốc: 春节 (Tết, nghỉ khoảng 8 ngày), 中秋节 (Trung thu), 国庆节 (Quốc khánh 1/10, nghỉ 7 ngày, đi đâu cũng đông)."},
# ---------------- 6
{"title":"Kể chuyện theo thứ tự","topic":"Mốc thời gian, trước sau; 才 và 就, 先…然后…最后, thời lượng sau sự việc",
"goals":["Dùng các từ chỉ thời gian: 以前, 以后, 后来, 最近, 前天…","Phân biệt 才 (muộn) và 就 (sớm)","Kể theo thứ tự với 先…然后…最后","Nói một việc đã xảy ra được bao lâu"],
"dialogue":[("王老师","龙，你来中国多长时间了？","Long, em đến Trung Quốc bao lâu rồi?"),("龙","我来中国半年了。以前我一直在越南学汉语。","Em đến Trung Quốc nửa năm rồi. Trước đây em vẫn học tiếng Trung ở Việt Nam."),("王老师","你今天怎么十点才来？","Hôm nay sao 10 giờ em mới đến?"),("龙","对不起，老师。地铁突然坏了，我等了半天。","Em xin lỗi thầy. Tàu điện ngầm đột nhiên hỏng, em đợi mãi."),("王老师","大卫八点就来了。你最近总是迟到。","David 8 giờ đã đến rồi. Gần đây em toàn đến muộn."),("龙","以后我先坐公交车，然后换地铁，最后走路过来。","Sau này em đi xe buýt trước, rồi đổi sang tàu điện ngầm, cuối cùng đi bộ tới."),("王老师","好。后天考试，你终于准备好了吗？","Được. Ngày kia thi, em chuẩn bị xong chưa?"),("龙","准备好了！我马上去复习。","Chuẩn bị xong rồi ạ! Em đi ôn bài ngay.")],
"grammar":[
{"title":"才 và 就: muộn và sớm","formula":"Thời gian + 才 + Động từ (muộn, khó) · Thời gian + 就 + Động từ + 了 (sớm, dễ)",
"explain":"Cùng đứng sau mốc thời gian nhưng thể hiện <b>cảm nhận của người nói</b>:<br>• <b>才</b>: muộn hơn mong đợi / khó khăn — 你怎么十点<b>才</b>来？ (10 giờ mới đến)<br>• <b>就</b>: sớm hơn mong đợi / dễ dàng — 大卫八点<b>就</b>来<b>了</b>。 (8 giờ đã đến rồi)<br>Câu 就 thường có 了 cuối, câu 才 thì <b>không</b> có 了.",
"examples":[("你怎么十点[才]来？","Sao 10 giờ bạn mới đến?"),("大卫八点[就]来了。","David 8 giờ đã đến rồi."),("他学了一年才会说。","Anh ấy học một năm mới biết nói."),("我看了一遍就懂了。","Tôi đọc một lần đã hiểu rồi.")],
"note":"Sai: 他十点才来了。 (才 không đi với 了 cuối câu)."},
{"title":"先…然后…最后…: trước tiên… sau đó… cuối cùng","formula":"先 + V1，然后 (再) + V2，最后 + V3",
"explain":"Kể các bước theo thứ tự. <b>先</b> và <b>再</b> là phó từ, đứng sau chủ ngữ; <b>然后</b>, <b>最后</b> đứng đầu vế câu:<br>我<b>先</b>坐公交车，<b>然后</b>换地铁，<b>最后</b>走路过来。",
"examples":[("我[先]坐公交车，[然后]换地铁。","Tôi đi xe buýt trước, rồi đổi sang tàu điện ngầm."),("我们先吃饭，然后去看电影。","Chúng ta ăn cơm trước, rồi đi xem phim."),("[最后]走路过来。","Cuối cùng đi bộ tới."),("你先洗手，再吃水果。","Con rửa tay trước rồi hãy ăn trái cây.")],
"note":"后来 (sau đó, chỉ chuyện đã qua) ≠ 然后 (rồi, dùng cả cho kế hoạch tương lai)."},
{"title":"Đã… được bao lâu: Động từ + (Tân ngữ) + Thời lượng + 了","formula":"Chủ ngữ + Động từ + Nơi/Tân ngữ + Thời lượng + 了",
"explain":"Với động từ xảy ra <b>một lần rồi duy trì trạng thái</b> (来, 到, 结婚, 毕业, 离开…), thời lượng đứng <b>sau</b> tân ngữ để nói từ lúc đó tới giờ đã bao lâu:<br>我来中国<b>半年了</b>。 (Tôi đến Trung Quốc được nửa năm rồi.)<br>他们结婚<b>三年了</b>。",
"examples":[("我来中国[半年]了。","Tôi đến Trung Quốc được nửa năm rồi."),("他们结婚三年了。","Họ cưới nhau được ba năm rồi."),("他离开北京很久了。","Anh ấy rời Bắc Kinh lâu rồi."),("你来中国多长时间了？","Bạn đến Trung Quốc bao lâu rồi?")],
"note":"Khác với HSK 2: 我学了三年汉语 (thời gian kéo dài của hành động học). Ở đây là khoảng thời gian <b>sau khi</b> việc xảy ra."}],
"tip":"Người Trung rất quý đúng giờ trong học tập, công việc. Đến muộn thì xin lỗi ngay: 对不起，我来晚了。"},
# ---------------- 7
{"title":"Đông Tây Nam Bắc","topic":"Phương hướng, đường phố; giới từ 向, 在…上/下/中, câu tồn hiện (xuất hiện)",
"goals":["Nói phương hướng Đông Tây Nam Bắc","Dùng 向 để chỉ hướng di chuyển hoặc đối tượng","Dùng 在…上 / 下 / 中 với nghĩa mở rộng","Mô tả có ai/cái gì xuất hiện ở đâu"],
"dialogue":[("游客","请问，火车站在哪个方向？","Xin hỏi, nhà ga ở hướng nào?"),("龙","在东边。您一直向东走，到了红绿灯向左拐。","Ở phía đông. Ông cứ đi thẳng về hướng đông, đến đèn giao thông thì rẽ trái."),("游客","附近有银行吗？","Gần đây có ngân hàng không?"),("龙","有，就在这条街中间，路边有很多人。","Có, ngay giữa con phố này, bên lề đường có nhiều người."),("游客","在北京，我常常找不到方向。","Ở Bắc Kinh tôi hay bị mất phương hướng."),("龙","北京的马路都是东西南北的，很容易记。","Đường ở Bắc Kinh đều theo Đông Tây Nam Bắc, rất dễ nhớ."),("游客","你看，前面走过来一个人，是不是警察？","Bạn nhìn kìa, phía trước có một người đi tới, có phải cảnh sát không?"),("龙","是的，您也可以向他问路。在生活中，大家都很热情。","Đúng vậy, ông cũng có thể hỏi đường anh ấy. Trong cuộc sống, mọi người đều rất nhiệt tình.")],
"grammar":[
{"title":"Giới từ 向: về phía, hướng tới (ai)","formula":"向 + Hướng/Nơi + Động từ · 向 + Người + Động từ (学习, 问, 介绍…)",
"explain":"<b>向</b> có hai cách dùng:<br>• Chỉ <b>hướng di chuyển</b> (gần nghĩa 往): <b>向</b>东走, <b>向</b>左拐<br>• Chỉ <b>đối tượng</b> của hành động: <b>向</b>他问路 (hỏi đường anh ấy), <b>向</b>老师学习 (học hỏi thầy)",
"examples":[("您一直[向]东走。","Ông cứ đi thẳng về hướng đông."),("到了红绿灯[向]左拐。","Đến đèn giao thông thì rẽ trái."),("您也可以[向]他问路。","Ông cũng có thể hỏi đường anh ấy."),("我们要向他学习。","Chúng ta phải học hỏi anh ấy.")],
"note":"往 chỉ dùng cho hướng di chuyển. Với người thì dùng 向: Sai: 往老师学习。"},
{"title":"在 + Danh từ + 上 / 下 / 中: nghĩa trừu tượng","formula":"在 + 生活/学习/工作/朋友的帮助 + 上 / 下 / 中",
"explain":"Ngoài nghĩa vị trí, 在…上/下/中 còn diễn tả <b>phương diện, điều kiện, quá trình</b>:<br>• 在…<b>上</b>: về mặt — 在学习<b>上</b> (về mặt học tập)<br>• 在…<b>下</b>: dưới điều kiện — 在老师的帮助<b>下</b> (nhờ sự giúp đỡ của thầy)<br>• 在…<b>中</b>: trong quá trình / phạm vi — 在生活<b>中</b> (trong cuộc sống)",
"examples":[("[在]生活[中]，大家都很热情。","Trong cuộc sống, mọi người đều rất nhiệt tình."),("在学习上，他很认真。","Về mặt học tập, anh ấy rất chăm chỉ."),("在老师的帮助下，我提高了很多。","Nhờ thầy giúp, tôi tiến bộ rất nhiều."),("这条街中间有一个银行。","Giữa con phố này có một ngân hàng.")],
"note":"中间 (ở giữa, vị trí cụ thể) khác 在…中 (trong, phạm vi trừu tượng)."},
{"title":"Câu tồn hiện: có ai/cái gì xuất hiện","formula":"Nơi chốn + Động từ + 过来/出来/进来… + (了) + Số lượng + Người/Vật",
"explain":"Mô tả <b>có người/vật xuất hiện</b> ở đâu đó, giống câu tồn tại ở HSK 2 nhưng dùng động từ chuyển động:<br>前面走<b>过来</b>一个人。 (Phía trước có một người đi tới.)<br>家里来<b>了</b>一位客人。 (Nhà có một vị khách đến.)<br>Người/vật mới xuất hiện đứng <b>sau</b> động từ và thường chưa xác định (一个人, 一位客人).",
"examples":[("前面走[过来]一个人。","Phía trước có một người đi tới."),("家里来了一位客人。","Nhà có một vị khách đến."),("教室里走出来两个学生。","Từ lớp học đi ra hai học sinh."),("路边停着很多汽车。","Bên lề đường đỗ nhiều ô tô.")],
"note":"Sai: 一个人前面走过来。 Nơi chốn đứng đầu, người xuất hiện đứng cuối."}],
"tip":"Bắc Kinh quy hoạch theo ô bàn cờ, nên người Bắc Kinh chỉ đường bằng 东西南北 chứ ít khi nói trái phải."},
# ---------------- 8
{"title":"Chuyến đi xa","topic":"Tàu cao tốc, hành lý, khách sạn; 只要…就, 如果…(的话)就, 一定 / 必须 / 不用",
"goals":["Nói chuyện đặt vé, lên tàu, khách sạn","Đặt điều kiện đủ với 只要…就","Giả định với 如果…(的话)，就","Nói mức bắt buộc: 必须, 一定, 不用"],
"dialogue":[("小米","龙，明天去上海，你准备好了吗？","Long, mai đi Thượng Hải, bạn chuẩn bị xong chưa?"),("龙","准备好了。我们坐高铁，八点出发。","Xong rồi. Tụi mình đi tàu cao tốc, 8 giờ xuất phát."),("小米","坐高铁必须带护照吗？","Đi tàu cao tốc bắt buộc mang hộ chiếu à?"),("龙","对，外国人一定要带护照。只要有护照，就可以检票上车。","Đúng, người nước ngoài nhất định phải mang hộ chiếu. Chỉ cần có hộ chiếu là soát vé lên tàu được."),("小米","如果高铁晚点的话，怎么办？","Nếu tàu cao tốc trễ giờ thì làm sao?"),("龙","不用担心，高铁很少晚点。","Không cần lo, tàu cao tốc rất ít khi trễ."),("小米","宾馆在哪儿？离车站远吗？","Khách sạn ở đâu? Cách ga có xa không?"),("龙","不远。我带了地图，只要跟着我走就行。","Không xa. Mình mang bản đồ rồi, chỉ cần đi theo mình là được.")],
"grammar":[
{"title":"只要…就…: chỉ cần… là…","formula":"只要 + Điều kiện，(Chủ ngữ) + 就 + Kết quả",
"explain":"<b>只要</b> nêu một <b>điều kiện đủ</b>: có điều kiện này là có kết quả, không cần gì thêm.<br><b>只要</b>有护照，<b>就</b>可以检票上车。<br>Sẽ học <b>只有…才…</b> (chỉ có… mới…) ở bài 10, nghĩa khác hẳn.",
"examples":[("[只要]有护照，[就]可以检票上车。","Chỉ cần có hộ chiếu là soát vé lên tàu được."),("只要跟着我走就行。","Chỉ cần đi theo tôi là được."),("只要你努力，就一定能学好。","Chỉ cần bạn cố gắng, nhất định học tốt."),("只要不下雨，我们就去爬山。","Chỉ cần không mưa, chúng ta sẽ đi leo núi.")],
"note":"就 đứng sau chủ ngữ của vế sau: 只要你来，我就高兴。 (Sai: 只要你来，就我高兴。)"},
{"title":"如果…(的话)，就…: nếu… thì…","formula":"如果 + Giả định (+ 的话)，(Chủ ngữ) + 就 + Kết quả",
"explain":"Câu giả định. <b>的话</b> đặt cuối vế giả định, có thể dùng cùng hoặc thay cho 如果:<br><b>如果</b>高铁晚点<b>的话</b>，怎么办？<br>明天下雨<b>的话</b>，我们<b>就</b>不去了。",
"examples":[("[如果]高铁晚点[的话]，怎么办？","Nếu tàu cao tốc trễ giờ thì làm sao?"),("如果你有时间，就来我家吧。","Nếu bạn có thời gian thì đến nhà tôi chơi nhé."),("明天下雨的话，我们就不去了。","Mai mưa thì chúng ta không đi nữa."),("如果我是你，我就去。","Nếu tôi là bạn, tôi sẽ đi.")],
"note":"Trong khẩu ngữ hay bỏ 如果, chỉ giữ 的话."},
{"title":"必须 · 一定 · 不用: mức độ bắt buộc","formula":"必须 + V (bắt buộc) · 一定 (要) + V (nhất định) · 不用 + V (không cần)",
"explain":"• <b>必须</b>: bắt buộc theo quy định: 坐高铁<b>必须</b>带证件。<br>• <b>一定 (要)</b>: nhấn mạnh quyết tâm hoặc lời dặn: 你<b>一定要</b>来！ <b>一定</b> còn nghĩa \"chắc chắn\": 他<b>一定</b>知道。<br>• <b>不用</b>: không cần (phủ định của 必须/要): <b>不用</b>担心。 Lưu ý phủ định của 必须 là <b>不用 / 不必</b>, không phải 不必须.",
"examples":[("坐高铁[必须]带护照吗？","Đi tàu cao tốc bắt buộc mang hộ chiếu à?"),("外国人[一定]要带护照。","Người nước ngoài nhất định phải mang hộ chiếu."),("[不用]担心。","Không cần lo."),("你一定要来！","Bạn nhất định phải đến nhé!")],
"note":"Sai: 你不必须来。 Đúng: 你不用来。"}],
"tip":"Mua vé tàu cao tốc Trung Quốc trên app 12306 (có tiếng Anh). Ga lớn kiểm tra an ninh như sân bay, nên đến sớm ít nhất 30 phút."},
# ---------------- 9
{"title":"Sở thích của em","topic":"Âm nhạc, phim, chụp ảnh; 不但…而且, 看起来 / 好像 / 看来, 一边…一边",
"goals":["Nói về sở thích giải trí, chụp ảnh, tin tức","Nối hai ý tăng tiến với 不但…而且","Đoán bằng 看起来, 好像, 看来","Nói làm hai việc cùng lúc với 一边…一边"],
"dialogue":[("安娜","龙，你平时喜欢做什么？","Long, ngày thường bạn thích làm gì?"),("龙","我喜欢拍照，也喜欢一边听音乐一边看书。","Mình thích chụp ảnh, cũng thích vừa nghe nhạc vừa đọc sách."),("安娜","你的相机看起来很新。","Máy ảnh của bạn trông mới quá."),("龙","是上个月买的。它不但很轻，而且照片特别好看。","Mua tháng trước. Nó không những nhẹ mà ảnh còn đẹp đặc biệt."),("安娜","你好像对画画儿也很感兴趣？","Hình như bạn cũng có hứng thú với vẽ tranh?"),("龙","对，我最喜爱的画家是徐悲鸿，他画的马很有名。","Đúng, họa sĩ mình thích nhất là Từ Bi Hồng, ngựa ông ấy vẽ rất nổi tiếng."),("安娜","看来你是个有文化的人！今天晚上有个音乐节目，一起去吗？","Xem ra bạn là người có văn hóa đấy! Tối nay có một chương trình ca nhạc, cùng đi không?"),("龙","好啊！我带上相机。","Được chứ! Mình mang theo máy ảnh.")],
"grammar":[
{"title":"不但…而且…: không những… mà còn…","formula":"(Chủ ngữ) + 不但 + A，而且 (还/也) + B",
"explain":"Nối hai ý theo hướng <b>tăng tiến</b> (B mạnh hơn hoặc thêm vào A):<br>它<b>不但</b>很轻，<b>而且</b>照片特别好看。<br>Nếu hai vế cùng chủ ngữ, chủ ngữ đứng <b>trước</b> 不但. Nếu khác chủ ngữ, mỗi chủ ngữ đứng sau liên từ: <b>不但</b>我去，<b>而且</b>他也去。",
"examples":[("它[不但]很轻，[而且]照片特别好看。","Nó không những nhẹ mà ảnh còn rất đẹp."),("他不但会说汉语，而且说得很好。","Anh ấy không những biết nói tiếng Trung mà còn nói rất giỏi."),("这儿的菜不但便宜，而且好吃。","Món ở đây không những rẻ mà còn ngon."),("不但我喜欢，而且我妈妈也喜欢。","Không chỉ tôi thích, mẹ tôi cũng thích.")],
"note":"Sai: 不但他会说汉语，而且说得很好。 (cùng chủ ngữ thì 他 phải đứng trước 不但)."},
{"title":"Đoán: 看起来 / 看上去 · 好像 · 看来","formula":"看起来/看上去 + Tính từ · 好像 + … · 看来，…",
"explain":"Ba cách đoán khác nhau:<br>• <b>看起来 / 看上去</b>: dựa vào <b>vẻ ngoài</b> — 你的相机<b>看起来</b>很新。<br>• <b>好像</b>: hình như, không chắc — 你<b>好像</b>对画画儿很感兴趣。<br>• <b>看来</b>: <b>rút ra kết luận</b> từ điều vừa thấy/nghe, đứng đầu câu — <b>看来</b>你是个有文化的人！",
"examples":[("你的相机[看起来]很新。","Máy ảnh của bạn trông mới quá."),("你[好像]对画画儿也很感兴趣？","Hình như bạn cũng thích vẽ tranh?"),("[看来]你是个有文化的人！","Xem ra bạn là người có văn hóa đấy!"),("他看上去很年轻。","Anh ấy trông rất trẻ.")],
"note":"好像 còn nghĩa \"giống như\": 她好像一个孩子。"},
{"title":"一边…一边…: vừa… vừa…","formula":"Chủ ngữ + 一边 + V1 + 一边 + V2",
"explain":"Làm <b>hai việc cùng lúc</b>, cùng một chủ ngữ:<br>我喜欢<b>一边</b>听音乐<b>一边</b>看书。<br>Khẩu ngữ có thể bỏ 一: 边吃边聊。",
"examples":[("我喜欢[一边]听音乐[一边]看书。","Tôi thích vừa nghe nhạc vừa đọc sách."),("我们一边吃饭一边聊天儿。","Chúng tôi vừa ăn cơm vừa nói chuyện."),("别一边走路一边玩手机。","Đừng vừa đi đường vừa chơi điện thoại."),("他一边唱一边跳。","Anh ấy vừa hát vừa nhảy.")],
"note":"Hai hành động phải làm được cùng lúc. Sai: 一边睡觉一边看书。"}],
"tip":"Từ Bi Hồng (徐悲鸿) là họa sĩ Trung Quốc nổi tiếng với tranh ngựa thủy mặc. Tranh ngựa thường được treo với ý \"马到成功\" (mã đáo thành công)."},
# ---------------- 10
{"title":"Kiên trì luyện tập","topic":"Thể thao, thi đấu; 只有…才, V + 起来 / 下去, câu lặp động từ",
"goals":["Nói về các môn thể thao, thi đấu, rèn luyện","Đặt điều kiện duy nhất với 只有…才","Nói bắt đầu (起来) và tiếp tục (下去)","Dùng câu lặp động từ để nói thời lượng / kết quả"],
"dialogue":[("大卫","龙，听说你参加了学校的运动会？","Long, nghe nói bạn tham gia hội thao của trường?"),("龙","对，我参加了羽毛球比赛，得了第二名。","Đúng, mình tham gia thi cầu lông, được giải nhì."),("大卫","真厉害！你练了多长时间？","Giỏi quá! Bạn luyện bao lâu?"),("龙","我打羽毛球打了三年了，每天都坚持锻炼。","Mình chơi cầu lông được ba năm rồi, ngày nào cũng kiên trì tập."),("大卫","我也想学，可是一打起来就累。","Mình cũng muốn học, nhưng hễ bắt đầu đánh là mệt."),("龙","刚开始都这样。只有坚持下去，水平才能提高。","Mới bắt đầu ai cũng vậy. Chỉ có kiên trì tiếp, trình độ mới nâng lên được."),("大卫","那你教我吧！这个周末去体育馆，怎么样？","Vậy bạn dạy mình đi! Cuối tuần này đi nhà thi đấu, thế nào?"),("龙","好啊，这是个好机会。我们一起努力！","Được, đây là cơ hội tốt. Chúng ta cùng cố gắng!")],
"grammar":[
{"title":"只有…才…: chỉ có… mới…","formula":"只有 + Điều kiện duy nhất，(Chủ ngữ) + 才 + Kết quả",
"explain":"<b>只有</b> nêu <b>điều kiện duy nhất / bắt buộc</b>: không có nó thì không có kết quả.<br><b>只有</b>坚持下去，水平<b>才</b>能提高。<br>So sánh: <b>只要…就</b> (bài 8) = điều kiện đủ, dễ; <b>只有…才</b> = điều kiện bắt buộc, khó.",
"examples":[("[只有]坚持下去，水平[才]能提高。","Chỉ có kiên trì tiếp, trình độ mới nâng lên."),("只有多练习，才能说得好。","Chỉ có luyện nhiều mới nói giỏi được."),("只有你去，他才会来。","Chỉ khi bạn đi, anh ấy mới đến."),("只有周末，我才有时间。","Chỉ cuối tuần tôi mới có thời gian.")],
"note":"Đi cặp cố định: 只要…就 · 只有…才. Không trộn 只有…就."},
{"title":"V + 起来 (bắt đầu) · V + 下去 (tiếp tục)","formula":"Động từ + 起来 (bắt đầu và tiếp diễn) · Động từ + 下去 (tiếp tục làm)",
"explain":"Nghĩa mở rộng của bổ ngữ xu hướng:<br>• <b>起来</b>: hành động <b>bắt đầu</b> rồi kéo dài — 一打<b>起来</b>就累, 他笑<b>起来</b>了, 下<b>起</b>雨<b>来</b>了 (tân ngữ chen giữa 起 và 来)<br>• <b>下去</b>: <b>tiếp tục</b> từ bây giờ về sau — 坚持<b>下去</b>, 说<b>下去</b>, 学<b>下去</b>",
"examples":[("我一打[起来]就累。","Hễ bắt đầu đánh là tôi mệt."),("只有坚持[下去]才能提高。","Chỉ có kiên trì tiếp mới tiến bộ."),("外面下起雨来了。","Bên ngoài bắt đầu mưa rồi."),("你说下去，我在听。","Bạn nói tiếp đi, tôi đang nghe.")],
"note":"Đã học 站起来 (đứng dậy) nghĩa hướng lên. 起来 ở đây là nghĩa \"bắt đầu\"."},
{"title":"Câu lặp động từ: V + O + V + 了 + thời lượng / 得 + …","formula":"Chủ ngữ + Động từ + Tân ngữ + Động từ (lặp) + 了 + Thời lượng · …+ 得 + Bổ ngữ",
"explain":"Khi động từ có tân ngữ mà muốn thêm <b>thời lượng</b> hoặc <b>bổ ngữ trạng thái</b>, phải <b>lặp động từ</b>:<br>我打羽毛球<b>打了</b>三年了。 (Tôi chơi cầu lông được ba năm rồi.)<br>他说汉语<b>说得</b>很好。 (đã gặp ở HSK 2)",
"examples":[("我打羽毛球[打]了三年了。","Tôi chơi cầu lông được ba năm rồi."),("他踢足球踢了两个小时。","Anh ấy đá bóng hai tiếng."),("她跳舞跳得很好。","Cô ấy nhảy rất đẹp."),("我等你等了半天。","Tôi đợi bạn mãi.")],
"note":"Sai: 我打羽毛球三年了 (thiếu động từ lặp, nghe như chưa xong câu). Cũng có thể nói: 我打了三年羽毛球。"}],
"tip":"Cầu lông (羽毛球) và bóng bàn (乒乓球) là hai môn rất phổ biến ở Trung Quốc. Sáng sớm ở công viên hay gặp các cụ tập thái cực quyền (太极拳)."},
]
